{"code":"from hermes_tools import terminal
cmd = r'''python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
out = '/root/output/result.xlsx'
wb = load_workbook(out, data_only=False)
ws = wb['Task']
for r in range(42, 48):
    label = ws.cell(r, 5).value
    for c in range(8, 13):
        col = get_column_letter(c)
        rng = f'{col}35:{col}40'
        if label == 'Minimum':
            formula = f'=MIN({rng})'
        elif label == 'Maximum':
            formula = f'=MAX({rng})'
        elif label == 'Median':
            formula = f'=MEDIAN({rng})'
        elif label == 'Simple mean':
            formula = f'=AVERAGE({rng})'
        elif label == '25th percentile':
            formula = f'=PERCENTILE.INC({rng},0.25)'
        elif label == '75th percentile':
            formula = f'=PERCENTILE.INC({rng},0.75)'
        else:
            raise ValueError(f'Unexpected label at E{r}: {label!r}')
        ws.cell(r, c).value = formula
wb.save(out)
print('Re-saved summary formulas with plain column ranges.')
for addr in ['H42','H43','H44','H45','H46','H47','L47']:
    print(addr, ws[addr].value)
PY'''
res=terminal(cmd, timeout=120)
print(res['output'])
print('EXIT_CODE', res['exit_code'])"}
